// Parse incoming request for delivery operations
const body = $input.item.json.body || $input.item.json;
const query = body.query || body.message || body.text || '';

let chatInput = query;
if (!chatInput && body.action) {
  // Structured request
  switch (body.action) {
    case 'transition':
      chatInput = `Transition story ${body.story_id} to status "${body.target_status}". ` +
        (body.reason ? `Reason: ${body.reason}` : '');
      break;
    case 'timeline':
      chatInput = `Show the delivery timeline for story ${body.story_id}.`;
      break;
    case 'environments':
      chatInput = `List all environments for story ${body.story_id}.`;
      break;
    case 'setup_env':
      chatInput = `Set up ${body.env_type || 'staging'} environment for story ${body.story_id}. ` +
        (body.url ? `URL: ${body.url}` : '');
      break;
    case 'estimate':
      chatInput = `Estimate effort for story ${body.story_id}. ` +
        (body.description ? `Description: ${body.description}` : '');
      break;
    default:
      chatInput = `Delivery task: ${JSON.stringify(body)}`;
  }
}

return {
  json: {
    chatInput,
    session_id: body.session_id || body.story_id || 'delivery-' + Date.now(),
    context: {
      story_id: body.story_id,
      action: body.action,
      source: body.source || 'webhook',
    }
  }
};

// Format the delivery agent response
const agentOutput = $input.item.json;
const context = $('Prepare Input').item.json.context;

return {
  json: {
    success: true,
    agent: 'delivery',
    response: agentOutput.output || agentOutput.text || agentOutput,
    context: {
      story_id: context.story_id,
      action: context.action,
    },
    timestamp: new Date().toISOString()
  }
};

